TYPES = {'index.html': 'text/html; charset=utf-8', 'app.js': 'application/javascript; charset=utf-8', 'style.css': 'text/css; charset=utf-8'}
FILES = {
    'index.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Human vs Bot</title>\n  <link rel="stylesheet" href="/style.css">\n</head>\n<body>\n  <main>\n    <h1>Human vs Bot</h1>\n    <p id="typed" class="typed">Press New Round.</p>\n    <p class="meta"><span>WPM <b id="wpm">-</b></span><span>Errors <b id="errs">-</b></span><span id="prog">0%</span></p>\n    <div class="btns">\n      <button id="btn-new">New Round</button>\n      <button id="btn-hum" disabled>Human</button>\n      <button id="btn-bot" disabled>Automated</button>\n    </div>\n    <div id="res" class="res hide"></div>\n    <p class="score">Score <span id="score">0</span> / <span id="rounds">0</span></p>\n  </main>\n  <script src="/app.js"></script>\n</body>\n</html>\n',
    'app.js': 'const $ = (id) => document.getElementById(id);\nconst typed = $("typed");\nconst wpmEl = $("wpm");\nconst errsEl = $("errs");\nconst progEl = $("prog");\nconst resEl = $("res");\nconst scoreEl = $("score");\nconst roundsEl = $("rounds");\nconst btnNew = $("btn-new");\nconst btnHum = $("btn-hum");\nconst btnBot = $("btn-bot");\n\nlet rid = null, replaying = false, abort = false, score = 0, rounds = 0;\n\nconst esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");\nconst sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n\nconst setGuess = (on) => {\n  btnHum.disabled = !on;\n  btnBot.disabled = !on;\n};\n\nconst render = (txt, err) => {\n  if (!txt) {\n    typed.innerHTML = \'<span class="cur"></span>\';\n    return;\n  }\n  if (err) {\n    typed.innerHTML = `${esc(txt.slice(0, -1))}<span class="err">${esc(txt.slice(-1))}</span><span class="cur"></span>`;\n  } else {\n    typed.innerHTML = `${esc(txt)}<span class="cur"></span>`;\n  }\n};\n\nconst reset = () => {\n  render("");\n  wpmEl.textContent = "-";\n  errsEl.textContent = "-";\n  progEl.textContent = "0%";\n  resEl.classList.add("hide");\n  setGuess(false);\n};\n\nconst replay = async (evs, len) => {\n  replaying = true;\n  let txt = "", errs = 0, n = 0;\n  render("");\n  for (let i = 0; i < evs.length; i++) {\n    if (abort) return;\n    const ev = evs[i];\n    const prev = i ? evs[i - 1] : null;\n    const d = prev ? Math.max(0, ev.t_ms - prev.t_ms) : 0;\n    if (d) await sleep(d);\n    if (ev.action !== "press") continue;\n    if (ev.key === "Backspace") {\n      txt = txt.slice(0, -1);\n      n = Math.max(0, n - 1);\n    } else {\n      txt += ev.key;\n      n++;\n      if (ev.is_error) errs++;\n    }\n    render(txt, ev.is_error);\n    wpmEl.textContent = String(Math.round(((n / Math.max(ev.t_ms, 1)) * 60000) / 5));\n    errsEl.textContent = String(errs);\n    progEl.textContent = `${Math.min(100, Math.round((n / len) * 100))}%`;\n  }\n};\n\nconst start = async () => {\n  if (replaying) return;\n  abort = true;\n  await sleep(30);\n  abort = false;\n  reset();\n  btnNew.disabled = true;\n  try {\n    const r = await fetch("/api/round", { method: "POST" });\n    const d = await r.json();\n    if (!r.ok) throw new Error(d.error || "failed");\n    rid = d.round_id;\n    await replay(d.events, d.snippet_length);\n    if (!abort) setGuess(true);\n  } catch (e) {\n    typed.textContent = e.message;\n  } finally {\n    btnNew.disabled = false;\n    replaying = false;\n  }\n};\n\nconst guess = async (g) => {\n  if (!rid || replaying) return;\n  setGuess(false);\n  try {\n    const r = await fetch("/api/guess", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({ round_id: rid, guess: g }),\n    });\n    const d = await r.json();\n    if (!r.ok) throw new Error(d.error || "failed");\n    rounds++;\n    if (d.correct) score++;\n    scoreEl.textContent = score;\n    roundsEl.textContent = rounds;\n    const s = d.stats || {};\n    resEl.classList.remove("hide");\n    resEl.innerHTML = [\n      `<p><b>${d.correct ? "Correct" : "Wrong"}</b> — actual: ${d.actual} (${d.profile || "-"})</p>`,\n      `<p>Model: ${d.model_label} (${d.model_confidence}%) · ML ${d.ml_score}% · rules ${d.rule_score}%</p>`,\n      `<ul>${(d.reasons || []).map((x) => `<li>${esc(x)}</li>`).join("")}</ul>`,\n      `<p>WPM ${s.wpm} · errors ${s.errors} · IKI ${s.mean_iki}ms · CV ${s.timing_cv} · pauses ${s.pause_count} · autocorr ${s.iki_autocorr}</p>`,\n    ].join("");\n    rid = null;\n  } catch (e) {\n    resEl.classList.remove("hide");\n    resEl.innerHTML = `<p>${esc(e.message)}</p>`;\n  }\n};\n\nbtnNew.onclick = start;\nbtnHum.onclick = () => guess("human");\nbtnBot.onclick = () => guess("automated");\n',
    'style.css': '* { box-sizing: border-box; margin: 0; padding: 0; }\n\nbody {\n  font-family: ui-monospace, "Cascadia Mono", Consolas, monospace;\n  background: #fff;\n  color: #000;\n  line-height: 1.5;\n}\n\nmain {\n  max-width: 640px;\n  margin: 48px auto;\n  padding: 0 16px;\n}\n\nh1 {\n  font-size: 18px;\n  font-weight: 600;\n  margin-bottom: 24px;\n}\n\n.typed {\n  min-height: 4em;\n  border: 1px solid #000;\n  padding: 12px;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.typed .err { text-decoration: line-through; }\n\n.typed .cur { border-left: 2px solid #000; }\n\n.meta {\n  display: flex;\n  gap: 24px;\n  margin: 12px 0 24px;\n  font-size: 13px;\n}\n\n.btns { display: flex; gap: 8px; flex-wrap: wrap; }\n\nbutton {\n  font: inherit;\n  background: #fff;\n  color: #000;\n  border: 1px solid #000;\n  padding: 8px 16px;\n  cursor: pointer;\n}\n\nbutton:disabled { opacity: 0.35; cursor: default; }\n\nbutton:not(:disabled):hover { background: #000; color: #fff; }\n\n.res {\n  margin-top: 24px;\n  border-top: 1px solid #000;\n  padding-top: 16px;\n  font-size: 13px;\n}\n\n.res.hide { display: none; }\n\n.res p { margin-bottom: 8px; }\n\n.res ul { margin: 8px 0; padding-left: 18px; }\n\n.score { margin-top: 32px; font-size: 13px; }\n',
}
